#!/usr/bin/env python3
"""Promote the generic-index Lane–Emden modules and the index-2 headline, its certificates and its
existence proof from Work/Math to Checked/Math (run 2026-11-08T0228Z).

Mechanical copy: namespaces Work.Math -> Checked.Math, `import Mathlib` -> specific modules, module docs
replaced by number-free text (check_prose rule 7). Statements and proofs otherwise byte-identical."""
import re, pathlib
ROOT = pathlib.Path(__file__).resolve().parents[3]
W, C = ROOT / "Work/Math", ROOT / "Checked/Math"
MODS = ["LENStart", "LENCell", "LENCellQ", "LE2Start", "LE2QData", "LE2Last", "LE2Chain", "LaneEmden2",
        "LE2ExistsLeft", "LE2ExistsStart", "LE2ExistsCell", "LE2ExistsData", "LE2Exists"]
DOCS = {
 "LENStart": "Lane–Emden equation of any integer index: the singular start. `start` encloses every solution with central value one (θ differentiable with derivative φ, φ continuous at the centre) near a polynomial reference whose residual is bounded by a multiple of the squared radius; closed by continuous induction. Generalised from `Checked.Math.LEStart` (index three); promoted verbatim from `Work/Math/LENStart.lean`.",
 "LENCell": "Lane–Emden equation of any integer index n: time-dependent validated cell step (`tube_cell_t`) and one Grönwall step `cell` for the system θ' = φ, φ' = −(two/ξ)φ − θⁿ with the state confined to a slab in θ; the defect of the second component is certified multiplied out. Generalised from `Checked.Math.LECell`; promoted verbatim from `Work/Math/LENCell.lean`.",
 "LENCellQ": "Lane–Emden equation of any integer index n: the validated cells of `Checked.Math.LENCell.cell` checked by kernel evaluation. All side conditions and both defect bounds of a cell are one proposition over the rationals (`CellProp n`), the defect polynomials computed from the cell's Taylor polynomials (`qpow` for the power θⁿ); a chain of cells is one Boolean, decided by the kernel. Promoted verbatim from `Work/Math/LENCellQ.lean`.",
 "LE2Start": "Generated by `runs/2026-11-08T0228Z/scripts/emit_len.py` (exact rational certificates; do not edit by hand): the singular start of the Lane–Emden chain of index two from the truncated series at the centre. Promoted verbatim from `Work/Math/LE2Start.lean`.",
 "LE2QData": "Generated by `runs/2026-11-08T0228Z/scripts/emit_len.py`: the validated cells of the Lane–Emden chain of index two as data; every side condition and defect bound decided by kernel evaluation over the rationals, one declaration per segment of cells. Promoted verbatim from `Work/Math/LE2QData.lean`.",
 "LE2Last": "Generated by `runs/2026-11-08T0228Z/scripts/emit_len.py`: the last cell of the Lane–Emden chain of index two (enclosure on the whole cell) and the facts read off it. Promoted verbatim from `Work/Math/LE2Last.lean`.",
 "LE2Chain": "Generated by `runs/2026-11-08T0228Z/scripts/emit_len.py`: chaining of the singular start, the kernel-checked segments and the last cell of the Lane–Emden chain of index two. Promoted verbatim from `Work/Math/LE2Chain.lean`.",
 "LE2ExistsLeft": "Lane–Emden equation of index two, existence near the centre: Banach fixed point of the scaled Volterra map with the clamped square nonlinearity (adapted from `Checked.Math.LEExistsLeft`). Promoted verbatim from `Work/Math/LE2ExistsLeft.lean`.",
 "LE2ExistsStart": "Generated: the singular start of the Lane–Emden chain of index two on the short initial interval used by the existence proof. Promoted verbatim from `Work/Math/LE2ExistsStart.lean`.",
 "LE2ExistsCell": "Lane–Emden equation of index two, existence away from the centre: the validated cells run on the flow of the clamped field, with box conditions decided per cell, so that the flow stays inside the clamps. Promoted verbatim from `Work/Math/LE2ExistsCell.lean`.",
 "LE2ExistsData": "Generated by `runs/2026-11-08T0228Z/scripts/gen_exists.py`: the cells of the clamped-flow chain of the Lane–Emden existence proof of index two as data, decided by kernel evaluation. Promoted verbatim from `Work/Math/LE2ExistsData.lean`.",
 "LE2Exists": "Lane–Emden equation of index two: existence of a solution meeting every hypothesis of `Checked.Math.LaneEmden2.laneEmden2_constants` (left piece by a fixed point, right piece by Picard–Lindelöf for the clamped field with the clamps shown inactive by the certified cells, glued). Promoted verbatim from `Work/Math/LE2Exists.lean`.",
}
for m in MODS:
    s = (W / f"{m}.lean").read_text()
    s = s.replace("Work.Math.", "Checked.Math.")
    assert "Work." not in s, m
    if m == "LaneEmden2":
        s = s.replace("import Mathlib\n", "import Mathlib.Analysis.Calculus.Deriv.MeanValue\nimport Mathlib.Topology.Order.IntermediateValue\n", 1)
        s = s.replace("frozen before proof, run 2026-11-08T0228Z", "frozen before proof in `Work/Math/LaneEmden2.lean`")
    else:
        assert "import Mathlib\n" not in s, m
        i = s.index("/-!")
        j = s.index("-/", i) + 2
        s = s[:i] + "/-! " + DOCS[m] + " -/" + s[j:]
    (C / f"{m}.lean").write_text(s)
    print("wrote", m)
